// Animated crowd dial — fills from 0 to target score with counting number.
// Perf notes: caches getComputedStyle (was called every frame), pre-renders the
// static track to an offscreen canvas, and keeps the parent drop-shadow filter
// on a SIBLING glow div so the canvas itself isn't re-rasterized 60×/sec.
const AnimatedDial = React.memo(function AnimatedDial({ score, color }) {
  const textRef = React.useRef(null);
  const canvasRef = React.useRef(null);

  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const cssSize = 60;
    const size = Math.round(cssSize * dpr);
    const center = size / 2;
    const radius = Math.round(26 * dpr);
    const lineWidth = Math.round(6 * dpr);
    canvas.width = size;
    canvas.height = size;

    const ctx = canvas.getContext('2d');

    // Cache the track color ONCE (was a getComputedStyle call per frame — expensive style recalc)
    const trackColor = getComputedStyle(document.documentElement).getPropertyValue('--border-default').trim() || '#334155';

    // Pre-render the static gray ring to an offscreen canvas — drawn once, blitted each frame.
    const trackCanvas = document.createElement('canvas');
    trackCanvas.width = size;
    trackCanvas.height = size;
    const tctx = trackCanvas.getContext('2d');
    tctx.beginPath();
    tctx.arc(center, center, radius, 0, Math.PI * 2);
    tctx.strokeStyle = trackColor;
    tctx.lineWidth = lineWidth;
    tctx.stroke();

    let raf;
    const start = performance.now();
    const ease = t => 1 - Math.pow(1 - t, 3);

    const draw = (val) => {
      ctx.clearRect(0, 0, size, size);
      ctx.drawImage(trackCanvas, 0, 0);
      if (val > 0) {
        ctx.beginPath();
        ctx.arc(center, center, radius, -Math.PI / 2, -Math.PI / 2 + (val / 100) * Math.PI * 2);
        ctx.strokeStyle = color;
        ctx.lineWidth = lineWidth;
        ctx.lineCap = 'round';
        ctx.stroke();
      }
    };

    const tick = now => {
      const t = Math.min((now - start) / 1200, 1);
      const val = ease(t) * score;
      draw(val);
      if (textRef.current) textRef.current.textContent = `${Math.round(val)}%`;
      if (t < 1) raf = requestAnimationFrame(tick);
    };

    draw(0);
    if (textRef.current) textRef.current.textContent = '0%';
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [score, color]);

  return (
    <div style={{ width: '60px', height: '60px', position: 'relative', flexShrink: 0 }}>
      {/* Glow lives on a SIBLING div — not on a parent of the canvas. Otherwise every
          canvas frame would force the browser to re-rasterize the drop-shadow. */}
      <div aria-hidden style={{ position: 'absolute', inset: 0, borderRadius: '50%', boxShadow: `0 4px 12px rgba(0,0,0,0.3), 0 0 8px ${color}30`, pointerEvents: 'none' }} />
      <canvas ref={canvasRef} style={{ width: '60px', height: '60px', position: 'absolute', top: 0, left: 0, transform: 'translateZ(0)' }} />
      <div style={{ position: 'absolute', inset: '6px', borderRadius: '24px', backgroundColor: 'var(--bg-card-solid)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <span ref={textRef} style={{ fontSize: 'var(--t-body)', fontWeight: '600', color, lineHeight: 1 }}>0%</span>
      </div>
    </div>
  );
});

// One-tap reality check under the crowd forecast: a report from someone at the
// venue becomes a dated training row (venue_feedback) AND calibrates the live
// score for everyone else. Self-contained state; remount per venue via key.
const CrowdRealityCheck = React.memo(function CrowdRealityCheck({ placeId, venueName, predicted }) {
  const [open, setOpen] = useState(false);
  const [sent, setSent] = useState(false);
  const [busy, setBusy] = useState(false);
  if (!placeId) return null;
  if (sent) {
    return (
      <p style={{ fontSize: 'var(--t-meta)', color: 'var(--text-secondary)', margin: '0 0 8px', fontWeight: '500' }}>
        Thanks. Real reports sharpen the forecast for everyone.
      </p>
    );
  }
  if (!open) {
    return (
      <button className="hit44"
        onClick={() => setOpen(true)}
        style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', padding: '6px 12px', margin: '0 0 8px', borderRadius: '10px', border: '1.5px solid var(--border-default)', backgroundColor: 'var(--bg-card-solid)', color: 'var(--text-secondary)', fontSize: 'var(--t-meta)', fontWeight: '600', cursor: 'pointer' }}
      >
        There now? Rate the crowd
      </button>
    );
  }
  const opts = [
    // Same words the score ladder uses (crowdLabelFor). 'Packed' was a sixth
    // vocabulary item that appears nowhere else in the product.
    { level: 1, label: 'Quiet' },
    { level: 2, label: 'Moderate' },
    { level: 3, label: 'Very Busy' },
  ];
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: '6px', flexWrap: 'wrap', margin: '0 0 8px', animation: 'fadeSlideIn 0.25s ease-out' }}>
      <span style={{ fontSize: 'var(--t-meta)', fontWeight: '500', color: 'var(--text-secondary)' }}>
        How busy is it actually:
      </span>
      {opts.map(o => (
        <button className="hit44"
          key={o.level}
          disabled={busy}
          onClick={async () => {
            setBusy(true);
            try {
              await submitVenueFeedback({
                venue_place_id: placeId,
                venue_name: venueName,
                crowd_level: o.level,
                predicted_score: typeof predicted === 'number' ? Math.round(predicted) : null,
              });
              setSent(true);
            } catch (err) {
              console.error('[RealityCheck] submit failed:', err);
              setBusy(false);
            }
          }}
          style={{ padding: '4px 12px', borderRadius: '8px', border: '1.5px solid var(--border-default)', backgroundColor: 'var(--bg-card-solid)', color: 'var(--text-primary)', fontSize: 'var(--t-meta)', fontWeight: '600', cursor: busy ? 'wait' : 'pointer' }}
        >
          {o.label}
        </button>
      ))}
    </div>
  );
});

// =============================================================================
// Offline screen with a playable minigame. Reviewers open apps in Airplane
// Mode hunting for the webview white screen; Flock hands them a bird instead.
// Original art (Flock palette, code-drawn bird) — only the mechanics are
// borrowed from every runner game since the dinosaur. Auto-dismisses the
// moment connectivity returns.
// =============================================================================
/* The offline game's bird is the real mascot, not a canvas ellipse.
   Both frames are started HERE, at module scope, so they load while the app
   is still online. The offline screen only mounts once the network is gone,
   and by then a cold fetch would fail. drawBird falls back to the old vector
   bird if either image has not decoded, so the game is never birdless. */
const GAME_SPRITES = (() => {
  if (typeof Image === 'undefined') return { perch: null, flap: null };
  const load = (src) => { const img = new Image(); img.src = src; return img; };
  return { perch: load('/birdie/game-perch.png'), flap: load('/birdie/game-flap.png') };
})();
const spriteReady = (img) => !!img && img.complete && img.naturalWidth > 0;

const FlockBirdGame = () => {
  const canvasRef = React.useRef(null);
  const wrapRef = React.useRef(null);
  const [best, setBest] = useState(() => parseInt(localStorage.getItem('flockBirdBest') || '0', 10));

  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return undefined;
    const W = 320, H = 400;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = W * dpr;
    canvas.height = H * dpr;
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);
    const rr = (x, y, w, h, r) => {
      // roundRect with fallback for older WebViews
      if (ctx.roundRect) { ctx.roundRect(x, y, w, h, r); return; }
      ctx.rect(x, y, w, h);
    };

    const CREAM = '#f1ede0', NAVY = '#16283d', NAVY_2 = '#1d3049', DIM = 'rgba(241,237,224,0.35)';
    const GROUND_H = 18, BIRD_X = 70;

    // ---- tuning (feel first: strong gravity, sharp flap, lagged tilt) ----
    const GRAVITY = 1380, FLAP = -395, PIPE_W = 56;
    const speedFor = (s) => Math.min(140 + s * 3.5, 205);   // ramps with score
    const gapFor = (s) => Math.max(152 - s * 1.2, 126);     // narrows with score

    let phase = 'ready'; // ready | play | dying | over
    let birdY = H / 2, vy = 0, tilt = 0, squash = 1;
    let pipes = [], score = 0, newBest = false;
    let groundX = 0, hitStopUntil = 0, flash = 0, shake = 0, diedAt = 0, scorePop = 1;
    let last = performance.now(), raf;

    // ---- mascot sprite ----
    // One scale for both frames so the bird does not change size mid-wingbeat.
    // The COLLISION box below is untouched (±10 x, ±7 y): this is an art swap,
    // and the game must not get harder or easier.
    const SPRITE_SCALE = 0.42;          // 96px flap frame -> ~40px on canvas
    const FLAP_FRAME_MS = 150;          // one wingbeat, not a flicker
    const MAX_DRAW_TILT = 0.44;         // ~25deg; a photo past this looks broken
    let flapFrameUntil = 0;

    // ---- backdrop: fixed stars + parallax skyline (0.35x speed) ----
    const stars = Array.from({ length: 24 }, (_, i) => ({
      x: (i * 97) % W, y: (i * 53) % (H - 160), r: (i % 3) * 0.4 + 0.5,
    }));
    const skyline = Array.from({ length: 12 }, (_, i) => ({
      x: i * 58, w: 34 + (i * 29) % 26, h: 34 + (i * 47) % 52,
    }));
    let skyX = 0;

    // ---- tiny synth (created on first user gesture; fails silently) ----
    let ac = null;
    const beep = (type, f0, f1, dur, vol) => {
      try {
        if (!ac) ac = new (window.AudioContext || window.webkitAudioContext)();
        const o = ac.createOscillator(), g = ac.createGain();
        o.type = type;
        o.frequency.setValueAtTime(f0, ac.currentTime);
        o.frequency.exponentialRampToValueAtTime(Math.max(f1, 1), ac.currentTime + dur);
        g.gain.setValueAtTime(vol, ac.currentTime);
        g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime + dur);
        o.connect(g).connect(ac.destination);
        o.start();
        o.stop(ac.currentTime + dur);
      } catch (_) { /* audio is garnish */ }
    };
    const sFlap = () => beep('square', 440, 620, 0.07, 0.05);
    const sScore = () => { beep('sine', 660, 660, 0.06, 0.06); setTimeout(() => beep('sine', 880, 880, 0.08, 0.06), 70); };
    const sHit = () => beep('sawtooth', 220, 60, 0.22, 0.09);

    const reset = () => { birdY = H / 2; vy = 0; tilt = 0; pipes = []; score = 0; newBest = false; };

    const flap = () => {
      const now = performance.now();
      if (phase === 'over') {
        if (now - diedAt > 500) { reset(); phase = 'ready'; }
        return;
      }
      if (phase === 'dying') return;
      if (phase === 'ready') phase = 'play';
      vy = FLAP;
      tilt = -0.38;      // snap nose-up on flap; gravity eases it back down
      squash = 0.82;     // quick squash, springs back
      flapFrameUntil = now + FLAP_FRAME_MS; // wings open for one beat
      sFlap();
    };

    const die = () => {
      phase = 'dying';
      hitStopUntil = performance.now() + 70;  // hit-stop: the world blinks
      flash = 0.55;
      shake = 9;
      sHit();
      const prevBest = parseInt(localStorage.getItem('flockBirdBest') || '0', 10);
      if (score > prevBest) {
        localStorage.setItem('flockBirdBest', String(score));
        setBest(score);
        newBest = true;
      }
    };

    // The original vector bird. Still the fallback for the first frame, and
    // for a cold offline start where neither PNG made it into the cache.
    const drawVectorBird = () => {
      ctx.scale(1 / squash, squash); // squash-and-stretch on flap
      ctx.fillStyle = CREAM;
      ctx.beginPath();
      ctx.ellipse(0, 0, 14, 11, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = NAVY;
      ctx.lineWidth = 2.5;
      ctx.lineCap = 'round';
      const w = vy < -60 ? -6 : 3; // wing up while rising
      ctx.beginPath();
      ctx.moveTo(-8, 0); ctx.quadraticCurveTo(-2, w, 5, 0);
      ctx.stroke();
      ctx.fillStyle = NAVY;
      ctx.beginPath(); ctx.arc(6, -3.5, 1.8, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.moveTo(13, -2); ctx.lineTo(19, 0); ctx.lineTo(13, 2); ctx.closePath(); ctx.fill();
    };

    const drawBird = (now) => {
      const wantFlap = now < flapFrameUntil;
      const img = wantFlap && spriteReady(GAME_SPRITES.flap)
        ? GAME_SPRITES.flap
        : (spriteReady(GAME_SPRITES.perch) ? GAME_SPRITES.perch : null);

      ctx.save();
      ctx.translate(BIRD_X, birdY);
      // Nose up while rising, nose down while falling, clamped so the photo
      // never reads as broken even in the death dive.
      ctx.rotate(Math.max(-MAX_DRAW_TILT, Math.min(MAX_DRAW_TILT, tilt)));

      if (!img) {
        drawVectorBird();
        ctx.restore();
        return;
      }

      // Half the squash of the vector bird: a photograph shows the stretch,
      // a flat shape hides it.
      const s = 1 + (squash - 1) * 0.5;
      ctx.scale(1 / s, s);
      const w = img.naturalWidth * SPRITE_SCALE;
      const h = img.naturalHeight * SPRITE_SCALE;
      // Both frames are tight crops, so they are placed by their centre.
      ctx.drawImage(img, -w / 2, -h / 2, w, h);
      ctx.restore();
    };

    const tick = (now) => {
      const dt = Math.min((now - last) / 1000, 0.033);
      last = now;
      const frozen = now < hitStopUntil;
      const speed = speedFor(score);

      if (!frozen) {
        squash += (1 - squash) * Math.min(1, dt * 14);
        scorePop += (1 - scorePop) * Math.min(1, dt * 10);

        if (phase === 'play' || phase === 'dying') {
          vy += GRAVITY * dt;
          birdY += vy * dt;
          // tilt lags velocity: floats level, then noses into the dive
          const target = phase === 'dying' ? 1.5 : Math.max(-0.38, Math.min(1.1, vy / 520));
          tilt += (target - tilt) * Math.min(1, dt * (phase === 'dying' ? 6 : 9));
          if (birdY < 8) { birdY = 8; vy = Math.max(vy, 0); } // ceiling clamps, never kills
        }

        if (phase === 'play') {
          groundX = (groundX - speed * dt) % 24;
          skyX = (skyX - speed * 0.35 * dt) % (12 * 58);
          const spacing = 185 + speed * 0.25; // constant distance apart as speed ramps
          if (!pipes.length || pipes[pipes.length - 1].x < W - spacing) {
            const gap = gapFor(score);
            const gapY = 60 + Math.random() * (H - GROUND_H - 120 - gap);
            pipes.push({ x: W + PIPE_W, gapY, gap, passed: false });
          }
          for (const p of pipes) {
            p.x -= speed * dt;
            if (!p.passed && p.x + PIPE_W < BIRD_X - 14) { p.passed = true; score++; scorePop = 1.45; sScore(); }
            // forgiving hitbox: ~80% of the visual bird
            if (p.x < BIRD_X + 10 && p.x + PIPE_W > BIRD_X - 10) {
              if (birdY - 7 < p.gapY || birdY + 7 > p.gapY + p.gap) die();
            }
          }
          pipes = pipes.filter(p => p.x > -PIPE_W);
          if (birdY > H - GROUND_H - 10) die();
        } else if (phase === 'dying') {
          if (birdY > H - GROUND_H - 8) { birdY = H - GROUND_H - 8; phase = 'over'; diedAt = now; }
        } else if (phase === 'ready') {
          birdY = H / 2 + Math.sin(now / 300) * 7;
          tilt = Math.sin(now / 300 + 1) * 0.06;
          groundX = (groundX - 40 * dt) % 24;
        }
        shake = Math.max(0, shake - dt * 34);
        flash = Math.max(0, flash - dt * 2.2);
      }

      // ================= draw =================
      ctx.save();
      if (shake > 0.5) ctx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);

      ctx.fillStyle = NAVY;
      ctx.fillRect(-12, -12, W + 24, H + 24);
      ctx.fillStyle = DIM;
      for (const s of stars) { ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2); ctx.fill(); }
      // parallax skyline silhouette
      ctx.fillStyle = NAVY_2;
      for (const b of skyline) {
        const bx = ((b.x + skyX) % (12 * 58) + 12 * 58) % (12 * 58) - 58;
        ctx.fillRect(bx, H - GROUND_H - b.h, b.w, b.h);
      }
      // pipes
      ctx.fillStyle = CREAM;
      for (const p of pipes) {
        ctx.beginPath();
        rr(p.x, -8, PIPE_W, p.gapY + 8, [0, 0, 7, 7]);
        rr(p.x, p.gapY + p.gap, PIPE_W, H - p.gapY - p.gap - GROUND_H, [7, 7, 0, 0]);
        ctx.fill();
        // lip on each pipe mouth gives them dimension
        ctx.fillRect(p.x - 3, p.gapY - 9, PIPE_W + 6, 9);
        ctx.fillRect(p.x - 3, p.gapY + p.gap, PIPE_W + 6, 9);
      }
      // scrolling ground with motion notches
      ctx.fillStyle = CREAM;
      ctx.fillRect(-12, H - GROUND_H, W + 24, GROUND_H + 12);
      ctx.fillStyle = 'rgba(22,40,61,0.22)';
      for (let x = groundX - 24; x < W + 24; x += 24) {
        ctx.beginPath();
        ctx.moveTo(x, H - GROUND_H); ctx.lineTo(x + 12, H - GROUND_H);
        ctx.lineTo(x + 6, H - GROUND_H + 6); ctx.closePath(); ctx.fill();
      }
      drawBird(now);
      // score with pop
      if (phase !== 'ready') {
        ctx.save();
        ctx.translate(W / 2, 52);
        ctx.scale(scorePop, scorePop);
        ctx.fillStyle = CREAM;
        ctx.font = "600 34px 'Fraunces', Georgia, serif";
        ctx.textAlign = 'center';
        ctx.fillText(String(score), 0, 0);
        ctx.restore();
      }
      if (phase === 'ready') {
        ctx.fillStyle = CREAM;
        ctx.font = "600 15px 'Hanken Grotesk', sans-serif";
        ctx.textAlign = 'center';
        ctx.fillText('Tap to fly', W / 2, H / 2 + 74);
      } else if (phase === 'over') {
        ctx.textAlign = 'center';
        ctx.fillStyle = CREAM;
        ctx.font = "600 17px 'Hanken Grotesk', sans-serif";
        ctx.fillText(newBest ? 'New best!' : `${score} pillar${score === 1 ? '' : 's'}`, W / 2, H / 2 - 10);
        ctx.font = "500 13px 'Hanken Grotesk', sans-serif";
        ctx.fillStyle = DIM;
        ctx.fillText('Tap to go again', W / 2, H / 2 + 14);
      }
      // death flash
      if (flash > 0) {
        ctx.fillStyle = `rgba(241,237,224,${flash})`;
        ctx.fillRect(-12, -12, W + 24, H + 24);
      }
      ctx.restore();
      raf = requestAnimationFrame(tick);
    };

    const onKey = (e) => { if (e.code === 'Space') { e.preventDefault(); flap(); } };
    const wrap = wrapRef.current;
    wrap.addEventListener('pointerdown', flap);
    window.addEventListener('keydown', onKey);
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      wrap.removeEventListener('pointerdown', flap);
      window.removeEventListener('keydown', onKey);
      try { if (ac) ac.close(); } catch (_) { /* already closed */ }
    };
  }, []);

  return (
    <div ref={wrapRef} style={{ touchAction: 'manipulation', cursor: 'pointer', userSelect: 'none', WebkitUserSelect: 'none' }}>
      <canvas ref={canvasRef} style={{ width: '320px', height: '400px', maxWidth: '86vw', borderRadius: '16px', display: 'block' }} />
      {best > 0 && (
        <p style={{ textAlign: 'center', fontSize: 'var(--t-meta)', color: 'rgba(241,237,224,0.5)', margin: '10px 0 0', fontWeight: '500' }}>Best: {best}</p>
      )}
    </div>
  );
};

const OfflineGate = () => {
  const [offline, setOffline] = useState(() => typeof navigator !== 'undefined' && !navigator.onLine);
  const [checking, setChecking] = useState(false);

  useEffect(() => {
    const goOnline = () => setOffline(false);
    const goOffline = () => setOffline(true);
    window.addEventListener('online', goOnline);
    window.addEventListener('offline', goOffline);
    return () => {
      window.removeEventListener('online', goOnline);
      window.removeEventListener('offline', goOffline);
    };
  }, []);

  if (!offline) return null;

  const retry = async () => {
    setChecking(true);
    try {
      // Any HTTP response at all (even a 401) proves the network path works
      await fetch(`${BASE_URL}/api/auth/me`, { cache: 'no-store' });
      setOffline(false);
    } catch (_) {
      // still offline — the game is right there
    } finally {
      setChecking(false);
    }
  };

  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 99999, backgroundColor: '#16283d', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: '18px', padding: '24px', fontFamily: "'Hanken Grotesk', -apple-system, sans-serif" }}>
      <div style={{ textAlign: 'center' }}>
        <h1 style={{ fontFamily: 'var(--font-display, Georgia)', fontSize: 'var(--t-display)', fontWeight: '600', color: '#f1ede0', margin: '0 0 6px', letterSpacing: '-0.005em' }}>You're offline</h1>
        <p style={{ fontSize: 'var(--t-body)', color: 'rgba(241,237,224,0.55)', margin: 0 }}>Your plans are safe. Flock reconnects on its own.</p>
      </div>
      <FlockBirdGame />
      <button className="hit44"
        onClick={retry}
        disabled={checking}
        style={{ padding: '12px 28px', borderRadius: '12px', border: 'none', backgroundColor: '#f1ede0', color: '#16283d', fontSize: 'var(--t-body)', fontWeight: '600', cursor: checking ? 'wait' : 'pointer', opacity: checking ? 0.7 : 1 }}
      >
        {checking ? 'Checking...' : 'Try again'}
      </button>
    </div>
  );
};

// The scroll-fade reveal component (IntersectionObserver) was deleted
// 2026-08-13. Four of its five usages wrapped the Nest feed with a staggered
// delay, so every return to the Nest tab replayed a fade and the flock list
// was briefly empty. Scroll-triggered reveals are on the absolute-ban list
// (SLOP-AUDIT A10 / H6). Content just is.

// ---------------------------------------------------------------------------
// EmptyMark — the photographed bird marks, for empty states only.
//
// These are the real mascots (cobalt Birdie and the cream one) mixed in with
// other birds, shot as transparent cutouts. They exist because short lists
// used to trail off into ~290px of blank canvas, which read as unfinished.
// Never put one on a state that already has content.
//
//   crowd  1024x498   the whole flock on a wire     transparent, any ground
//   steps   864x290   a few birds along a branch    transparent, any ground
//   money  1024x1024  birds sharing a banknote      CREAM GROUND, never navy
//
// -400 is the 1x and the full file is the 2x, the same pairing BirdieBird
// uses. object-fit: contain is load-bearing: the marks have very different
// aspect ratios (steps is nearly 3:1) and without it a width clamp at 390px
// would stretch them. Decorative, so alt="" + aria-hidden — the copy beside
// them carries the meaning.
//
// Both densities are served as WebP, with the PNGs kept as the <picture>
// fallback. The 2x entry was the expensive one and nothing was compressing it:
// mark-crowd.png is 1,194,700 bytes against 391,212 for the WebP, and
// mark-money.png 2,088,033 against 141,310. That weight is inside the Capacitor
// download, not just a slow request. The `-400` WebP files predate this and are
// also served by the marketing site, so they are used exactly as they are.
//
// LANDMINE for a new `name`: all FOUR files have to exist. <picture> falls back
// to the <img> when the browser cannot decode the source's TYPE, never when the
// chosen URL 404s, so a missing .webp is a broken image and not a silent
// downgrade to the PNG. crowd, steps and money each have all four today.
//
// display:contents on the <picture> keeps this component's layout identical to
// the bare <img> it replaced: the wrapper contributes no box, so the img is
// still the element the parent flex column lays out.
// ---------------------------------------------------------------------------
const EmptyMark = ({ name, height = 160, style }) => (
  <picture style={{ display: 'contents' }}>
    <source type="image/webp" srcSet={`/marks/mark-${name}-400.webp 1x, /marks/mark-${name}.webp 2x`} />
    <img
      src={`/marks/mark-${name}-400.png`}
      srcSet={`/marks/mark-${name}-400.png 1x, /marks/mark-${name}.png 2x`}
      alt=""
      aria-hidden="true"
      loading="lazy"
      draggable="false"
      style={{ display: 'block', height: `${height}px`, width: 'auto', maxWidth: '100%', objectFit: 'contain', ...style }}
    />
  </picture>
);

// The backend stores venue photo URLs as RELATIVE proxy paths
// (/api/venues/photo?ref=...) so senders can't smuggle tracking hosts.
// Resolve to the API origin whenever a stored value is rendered.
const resolveVenuePhoto = (u) => (u && u.startsWith('/api/') ? `${BASE_URL}${u}` : u || null);

// Chat photos travel INSIDE the message body as a data: URL, on whichever
// transport is up. Socket.IO was raised to 8MB for exactly that; express.json()
// is still 1mb, so a photo over roughly 750KB sends fine on the socket and 413s
// the instant the REST fallback is used — the transport that only comes out
// when the network is already bad, which is the case the fallback exists for.
// Sizing the payload to fit BOTH is the client's half of that; the body limit
// wants raising too (reported, backend file).
//
// It also keeps the send honest about time: a 6MB base64 string is a slow
// upload with no progress bar behind it.
const CHAT_IMAGE_MAX_EDGE = 1600;
const CHAT_IMAGE_MAX_CHARS = 700 * 1024;
const CHAT_IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
const dataUrlMime = (u) => (typeof u === 'string' ? ((/^data:([^;,]+)[;,]/.exec(u) || [])[1] || '') : '');

const prepareChatImage = (dataUrl) => new Promise((resolve) => {
  if (typeof dataUrl !== 'string' || !dataUrl.startsWith('data:image/')) {
    resolve({ error: "That photo couldn't be read. Try another one." });
    return;
  }
  const mime = dataUrlMime(dataUrl);
  // Already small enough and already a format the server accepts: leave it
  // alone. Re-encoding a photo that does not need it only costs quality.
  if (dataUrl.length <= CHAT_IMAGE_MAX_CHARS && CHAT_IMAGE_TYPES.includes(mime)) {
    resolve({ dataUrl });
    return;
  }
  // An animated GIF is refused server-side on purpose. Re-encoding one would
  // smuggle a still frame past that rule, so an oversized GIF is simply too
  // big to send.
  if (mime === 'image/gif') {
    resolve({ error: 'That GIF is too big to send. Try one under 1 MB.' });
    return;
  }
  const img = new Image();
  img.onload = () => {
    const longest = Math.max(img.naturalWidth, img.naturalHeight);
    if (!longest) {
      resolve({ error: "That photo couldn't be read. Try another one." });
      return;
    }
    const scale = Math.min(1, CHAT_IMAGE_MAX_EDGE / longest);
    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, Math.round(img.naturalWidth * scale));
    canvas.height = Math.max(1, Math.round(img.naturalHeight * scale));
    const ctx = canvas.getContext('2d');
    if (!ctx) {
      resolve({ error: "That photo couldn't be prepared. Try another one." });
      return;
    }
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    let out = canvas.toDataURL('image/jpeg', 0.82);
    for (let q = 0.65; out.length > CHAT_IMAGE_MAX_CHARS && q >= 0.4; q -= 0.15) {
      out = canvas.toDataURL('image/jpeg', q);
    }
    if (out.length > CHAT_IMAGE_MAX_CHARS) {
      resolve({ error: 'That photo is too big to send. Try a smaller one.' });
      return;
    }
    resolve({ dataUrl: out });
  };
  img.onerror = () => resolve({ error: "That photo couldn't be read. Try another one." });
  img.src = dataUrl;
});

// Does this optimistic bubble (or pending send) describe the row the server
// just echoed back? Text alone is not enough once a message can be an image
// with no text: every photo would match every other photo's empty body, and the
// wrong bubble would be reconciled while the right one hung there pending.
// `local` is either a rendered message (image on `image_url` in DMs, `image` in
// flock chat) or a stored send payload; `server` is the socket row.
//
// The server trims the text it stores, so the comparison trims both sides:
// sending "hi " matched nothing on the way back, and the bubble sat pending
// until it declared itself failed on a message that had saved fine.
const sameSend = (local, server) => {
  if (!local || !server) return false;
  const localImage = local.image_url || local.image || null;
  const trim = (v) => (typeof v === 'string' ? v.trim() : '');
  return trim(local.text) === trim(server.message_text)
    && (local.message_type || 'text') === (server.message_type || 'text')
    && localImage === (server.image_url || null);
};

// A history fetch replaces the whole message list, and it cannot know about a
// send the server never confirmed. Carry those bubbles forward — otherwise
// stepping out of a chat and back in silently deletes a failed photo and the
// retry attached to it — minus any the history now contains, which is the case
// where the send actually landed while the client was giving up on it.
const keepUnsettled = (local, history) => (local || []).filter((m) => (m.pending || m.failed)
  && !(history || []).some((h) => sameSend(m, {
    message_text: h.text,
    message_type: h.message_type,
    image_url: h.image_url || h.image || null,
  })));

// One-line summary of a message for the places that can only show one line: the
// conversation list, the reply bar, a quoted reply.
//
// A photo message has NO text. It used to be sent with the literal word "Photo"
// as its body, which made every preview work by accident and put a word nobody
// typed into the database, into push notification bodies and into chat search
// results. The body is empty now and the WORD lives here, in the one layer that
// actually needs a label. Do not push it back down into the message.
//
// `hadContent` covers the conversation list loaded from GET /api/dm, which
// returns the stored body and nothing else: an empty body on a conversation that
// demonstrably has messages can only be an image-only message, so it reads as a
// photo rather than as "no messages".
const messagePreview = (m) => {
  if (!m) return '';
  const text = typeof m.text === 'string' ? m.text.trim() : '';
  if (text) return text;
  if (m.message_type === 'venue_card' || m.venue_data) return 'Venue';
  if (m.message_type === 'image' || m.image_url || m.image || m.hadContent) return 'Photo';
  return '';
};

// A guest's identity arrives in two forms and the roster used to keep only the
// wrong one. `id` is the namespaced string the roster is keyed on ("guest:12",
// deliberately non-numeric so it can never be mistaken for a user id); the REST
// roster also sends `guest_id`, the plain `guest_rsvps` row id. Reporting needs
// the number, because POST /api/reports validates content_id as an integer.
//
// Dropping it is why reporting a guest name was unreachable: the content type,
// the sheet's wording, the flock-membership visibility gate and migration 016
// (which widened the CHECK constraint so those reports stop 500ing) all shipped,
// and the client still had nothing to put in content_id.
//
// The socket event carries only the namespaced form, so parse that as the
// fallback rather than leaving a guest who just arrived unreportable until the
// next refetch.
const guestRsvpId = (g) => {
  const raw = g?.guest_id != null
    ? g.guest_id
    : String(g?.id ?? g?.guestId ?? '').replace(/^guest:/, '');
  const n = Number(raw);
  return Number.isInteger(n) && n > 0 ? n : null;
};

// The server talks about votes as { venue_name, venue_id, voters, guest_count }
// where voters are either { id, name } rows (GET /votes) or plain names (vote
// POST + the new_vote socket event). The UI reads { venue, type, voters, ... }
// with the signed-in user shown as 'You'. Everything that lands in flock.votes
// goes through here so peer votes stop rendering as undefined venues.
const normalizeVotes = (raw, me, previous = []) => {
  if (!Array.isArray(raw)) return Array.isArray(previous) ? previous : [];
  const myId = me?.id != null ? String(me.id) : null;
  const myName = me?.name || null;
  return raw
    .map((v) => {
      const venue = v.venue || v.venue_name || '';
      const prior = (Array.isArray(previous) ? previous : []).find((p) => p.venue === venue);
      return {
        venue,
        type: v.type || prior?.type || 'Venue',
        place_id: v.place_id || v.venue_id || prior?.place_id || null,
        voters: (v.voters || []).map((p) => {
          if (typeof p === 'string') return myName && p === myName ? 'You' : p;
          if (!p || typeof p !== 'object') return '';
          if (myId != null && String(p.id) === myId) return 'You';
          return p.name || '';
        }).filter(Boolean),
        guestCount: Number(v.guest_count ?? v.guestCount ?? 0) || 0,
      };
    })
    .filter((v) => v.venue);
};

// Members who voted plus guest-link votes, which have no identities.
const voteTotal = (v) => (v?.voters?.length || 0) + (v?.guestCount || 0);

// "1 members" was on screen in three places. One label, counted once.
const memberCountLabel = (flock) => {
  const n = (Array.isArray(flock?.members) && flock.members.length) || flock?.memberCount || flock?.member_count || 0;
  return `${n} member${n === 1 ? '' : 's'}`;
};

/* ═══════════════════════════════════════════════════════════════════
   WHEN. The create screen and the flock "Details" panel both pick a day
   from a relative chip ("Tonight", "This Weekend") and an hour from a
   chip ("9 PM"). Neither of those is a timestamp, and for a long time
   neither of them was sent: every flock landed with event_time NULL,
   which is why they all read "TBD" and never reached the Plans calendar.

   These two helpers turn the pair into a real instant. new Date(y, m, d, h)
   builds the date in the browser's own timezone, so 9 PM means 9 PM where
   the user is standing; .toISOString() hands the API the UTC instant it
   stores (backend/routes/flocks.js validates event_time with isISO8601).
   ═══════════════════════════════════════════════════════════════════ */
const FLOCK_DAY_CHOICES = ['Tonight', 'Tomorrow', 'This Weekend', 'Next Week'];
const FLOCK_HOUR_CHOICES = ['7 PM', '8 PM', '9 PM', '10 PM', '11 PM'];

const parseHourChoice = (label) => {
  const m = /^\s*(\d{1,2})\s*(AM|PM)\s*$/i.exec(String(label || ''));
  if (!m) return 21;
  const h = parseInt(m[1], 10) % 12;
  return /pm/i.test(m[2]) ? h + 12 : h;
};

const resolveEventTime = (dayLabel, hourLabel, now = new Date()) => {
  const d = new Date(now.getFullYear(), now.getMonth(), now.getDate(), parseHourChoice(hourLabel), 0, 0, 0);
  switch (dayLabel) {
    case 'Tomorrow':
      d.setDate(d.getDate() + 1);
      break;
    case 'This Weekend': {
      const day = d.getDay(); // 0 Sun … 6 Sat
      if (day === 6 || day === 0) {
        // Already the weekend. Keep today unless that hour is behind us.
        if (d <= now) d.setDate(d.getDate() + (((6 - day + 7) % 7) || 7));
      } else {
        d.setDate(d.getDate() + ((6 - day + 7) % 7));
      }
      break;
    }
    case 'Next Week':
      d.setDate(d.getDate() + 7);
      break;
    case 'Tonight':
    default:
      // A "tonight" slot that has already gone by means tomorrow night.
      if (d <= now) d.setDate(d.getDate() + 1);
      break;
  }
  return d;
};

// One label for a flock's time, used by every surface that shows one.
const formatEventTime = (iso) => {
  if (!iso) return 'TBD';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return 'TBD';
  return d.toLocaleString([], { weekday: 'short', hour: 'numeric', minute: '2-digit' });
};

/* Momentum. The server scores a brand-new flock at 50/100 (it hands out a
   full 20 points for "no budget to collect" and 30 for the creator's own
   RSVP), so a plan with no venue, no time and one person read "Almost
   There". The score is still useful as a bar; the STAGE is re-derived here
   from the three facts a person would actually check. */
const MOMENTUM_STAGES = [
  { key: 'idea', label: 'Idea', color: '#94a3b8' },
  { key: 'building', label: 'Building', color: '#f59e0b' },
  { key: 'almost_there', label: 'Almost There', color: '#F59E0B' },
  { key: 'locked_in', label: 'Locked In', color: '#22c55e' },
  { key: 'lets_go', label: "Let's Go", color: '#4a7ba7' },
];

const momentumStageKey = (m) => {
  if (!m) return 'idea';
  const hasPeople = (m.accepted || 0) >= 2;
  const signals = [!!m.hasVenue, !!m.hasTime, hasPeople].filter(Boolean).length;
  if (signals === 3) return (m.score || 0) >= 85 ? 'lets_go' : 'locked_in';
  if (signals === 2) return 'almost_there';
  if (signals === 1) return 'building';
  return 'idea';
};

/* ── LIST SKELETON ───────────────────────────────────────────────────────
   Three cards in the shape of the rows they stand in for. Every list that
   fetches on mount uses this, because the alternative is what the app used to
   do: render the empty state during the fetch, so a returning user with six
   flocks was told "No flocks yet" for as long as the network took. Empty
   states are a claim about the user's data and must not be made before the
   data arrives. (SLOP-AUDIT.md rule 10: skeletons for feeds and pages.) */
const ListSkeleton = ({ count = 3, thumb = 46, thumbRadius = 14, label = 'Loading' }) => (
  <div role="status" aria-label={label}>
    {Array.from({ length: count }, (_, i) => (
      <div key={i} style={{ display: 'flex', gap: '12px', padding: '12px', marginBottom: '10px', borderRadius: '14px', border: '1px solid var(--border-subtle)', backgroundColor: 'var(--bg-card-solid)' }}>
        <div className="skeleton" style={{ width: `${thumb}px`, height: `${thumb}px`, borderRadius: `${thumbRadius}px`, flexShrink: 0 }} />
        <div style={{ flex: 1, minWidth: 0, paddingTop: '4px' }}>
          <div className="skeleton" style={{ width: '60%', height: '14px', borderRadius: '4px', marginBottom: '8px' }} />
          <div className="skeleton" style={{ width: '40%', height: '11px', borderRadius: '4px', marginBottom: '10px' }} />
          <div className="skeleton" style={{ width: '80%', height: '10px', borderRadius: '4px' }} />
        </div>
      </div>
    ))}
  </div>
);

/* ── FLOCK TILE ──────────────────────────────────────────────────────────
   The 46px square next to a flock in the Messages list. It used to be one of
   five stock JPEGs (public/group-avatars/flock-1..5.jpg) picked by hashing the
   flock id, so a real group called "Sarah's birthday" was illustrated with a
   dog in sunglasses. That is fabricated decoration standing in for user
   content, so the files are gone and the tile is now the flock's own initial
   on one of four brand swatches, keyed off the flock id so a given flock keeps
   the same colour forever. A flock that has picked a venue shows the venue
   photo instead — that one IS the flock's own content. */
const FLOCK_TILE_SWATCHES = [
  { bg: '#1e293b', fg: '#f1ede0' }, // navy
  { bg: '#2d5a87', fg: '#f1ede0' }, // steel
  { bg: '#e8e0d5', fg: '#1e293b' }, // cream
  { bg: '#c8b696', fg: '#1e293b' }, // sand
];

const flockTileSwatch = (flockId) => {
  const seed = String(flockId || '');
  let hash = 0;
  for (let i = 0; i < seed.length; i++) hash = (hash * 31 + seed.charCodeAt(i)) >>> 0;
  return FLOCK_TILE_SWATCHES[hash % FLOCK_TILE_SWATCHES.length];
};

const flockTileInitial = (name) => {
  const ch = String(name || '').trim().charAt(0);
  return ch ? ch.toUpperCase() : '?';
};

// ═══════════════════════════════════════════════════════════════════════════
// ONE crowd vocabulary for the whole app.
//
// backend/services/crowdEngine.js getLabel() owns these five bands and these
// cut points. This file used to carry FIVE different local ladders, most of
// them three bands, so the same score of 65 read "Moderate" in the venue
// sheet, "Busy" in the search row and "Very Busy" in the alternatives list,
// while the website called it "Busy". Same story for the colour: a 65 was red
// on the site and amber in the app because the app's threshold was 70.
//
// Never inline another ladder. Call these.
// ═══════════════════════════════════════════════════════════════════════════
// A crowd reading is only 'live' for so long. Shared by the LIVE/ESTIMATED
// chip and by the back-navigation snapshot check so they never disagree about
// what counts as current.
const CROWD_FRESH_MS = 5 * 60 * 1000;
const crowdLabelFor = (score) => {
  if (!Number.isFinite(score)) return null;
  if (score <= 20) return 'Quiet';
  if (score <= 40) return 'Not Busy';
  if (score <= 60) return 'Moderate';
  if (score <= 80) return 'Busy';
  return 'Very Busy';
};
// Red at 61+, matching the site. `c` is the theme palette when a caller has it.
const crowdColorFor = (score, c) => {
  if (!Number.isFinite(score)) return null;
  if (score > 60) return (c && c.red) || '#EF4444';
  if (score > 40) return (c && c.amber) || '#F59E0B';
  return '#22C55E';
};

// Contact sync runs on the Contacts Picker API, which does not exist in
// WKWebView. Inside the iOS app the answer is therefore always "no", and a
// Contacts tab there could only ever apologise and name the platform it does
// work on, which is both a dead end and guideline 2.3.10. Checking for native
// alongside the API keeps the tab out of the iOS build entirely.
function contactSyncAvailable() {
  if (typeof navigator === 'undefined' || typeof window === 'undefined') return false;
  if (window.Capacitor?.isNativePlatform?.()) return false;
  return 'contacts' in navigator && 'ContactsManager' in window;
}

// Memoized VenueCard — unified design for both DMs and Flocks
const VenueCard = React.memo(({ venue, onViewDetails, onVote, colors: c, Icons: I, getCategoryColor: gcc }) => {
  const rating = venue.stars || venue.rating || null;
  const price = venue.price || (venue.price_level ? '$'.repeat(venue.price_level) : null);
  const address = venue.addr || venue.formatted_address || '';
  // Real crowd data only. This used to be
  //   Math.round(20 + (name.charCodeAt(0) * 37) % 60)
  // which is a number invented from the venue's first letter and rendered to
  // the user as a measurement. It is also why surfaces disagreed about the
  // same venue. No score yet means no crowd row, exactly as Birdie's cards do.
  const crowd = typeof venue.crowd === 'number' ? venue.crowd : null;
  const crowdColor = crowdColorFor(crowd);
  return (
    <div style={{
      backgroundColor: 'var(--bg-card-solid)',
      borderRadius: '16px',
      overflow: 'hidden',
      boxShadow: '0 4px 20px rgba(0,0,0,0.12)',
      border: '1px solid var(--border-subtle)',
      width: '100%',
      maxWidth: '280px',
      animation: 'cardSlideIn 0.4s ease-out'
    }}>
      {/* A venue with no photo used to leave a blank block. The placeholder is
          Birdie in cream, deliberately low contrast so it recedes next to the
          real photographs beside it. Only on the LARGE slots: at the 44px
          thumbnail size in list rows a photograph is mud, and those keep their
          letter. */}
      <img
        src={venue.photo_url ? resolveVenuePhoto(venue.photo_url) : '/marks/venue-placeholder.jpg'}
        alt={venue.photo_url ? venue.name : ''}
        loading="lazy"
        style={{ width: '100%', height: '160px', objectFit: 'cover', display: 'block' }}
        onError={(e) => { e.target.src = '/marks/venue-placeholder.jpg'; }}
      />

      <div style={{ padding: '14px' }}>
        <h4 style={{ fontSize: 'var(--t-body)', fontWeight: '600', color: c.navy, margin: '0 0 4px' }}>{venue.name}</h4>

        {address && (
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '10px' }}>
            {I.mapPin(c.textSecondary, 12)}
            <span style={{ fontSize: 'var(--t-meta)', color: 'var(--text-secondary)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{address}</span>
          </div>
        )}

        <div style={{ display: 'flex', gap: '12px', marginBottom: '12px' }}>
          {price && <span style={{ fontSize: 'var(--t-meta)', color: c.navy, fontWeight: '500' }}>{price}</span>}
          {rating && (
            <div style={{ display: 'flex', alignItems: 'center', gap: '3px' }}>
              {I.starFilled('#fbbf24', 12)}
              <span style={{ fontSize: 'var(--t-meta)', color: c.navy, fontWeight: '500' }}>{rating}</span>
            </div>
          )}
        </div>

        {crowd != null && (
          <div style={{ backgroundColor: 'var(--bg-tertiary)', borderRadius: '12px', padding: '10px 12px', marginBottom: '12px', border: '1px solid var(--border-default)' }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '6px' }}>
              <span style={{ fontSize: 'var(--t-meta)', color: 'var(--text-secondary)', fontWeight: '500' }}>{crowdLabelFor(crowd)}</span>
              <div style={{ backgroundColor: `${crowdColor}20`, color: crowdColor, padding: '2px 8px', borderRadius: '10px', fontSize: 'var(--t-meta)', fontWeight: '500' }}>{crowd}%</div>
            </div>
            <div style={{ width: '100%', height: '6px', backgroundColor: 'var(--pill-bg)', borderRadius: '3px', overflow: 'hidden' }}>
              <div style={{ height: '100%', width: `${crowd}%`, backgroundColor: crowdColor, borderRadius: '3px', transition: 'width 0.5s ease-out' }} />
            </div>
          </div>
        )}

        <div style={{ display: 'flex', gap: '8px' }}>
          {(venue.place_id || venue.id) && (
            /* stopPropagation on both buttons: a venue card posted into a chat
               is wrapped in a tap target that opens the reaction and report
               row, so a tap on View Details or Vote must not also toggle it. */
            <button className="hit44 glass-btn glass-secondary" onClick={(e) => { e.stopPropagation(); onViewDetails(); }} style={{ flex: 1, padding: '10px', borderRadius: '10px', border: `2px solid ${c.navy}`, backgroundColor: 'var(--bg-card-solid)', color: c.navy, fontSize: 'var(--t-meta)', fontWeight: '600', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '4px', transition: 'opacity 0.2s ease' }}>
              {I.eye(c.navy, 14)} View Details
            </button>
          )}
          <button className="hit44 glass-btn glass-navy" onClick={(e) => { e.stopPropagation(); const btn = e.currentTarget; if (!btn.classList.contains('btn-confirmed')) { btn.classList.add('btn-confirmed'); setTimeout(() => btn.classList.remove('btn-confirmed'), 1100); } onVote(); }} style={{ flex: 1, padding: '10px', borderRadius: '10px', border: 'none', background: `linear-gradient(135deg, ${c.navy}, ${c.navyMid})`, color: 'white', fontSize: 'var(--t-meta)', fontWeight: '600', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '4px', boxShadow: '0 2px 8px rgba(13,40,71,0.10)', transition: 'opacity 0.2s ease', position: 'relative', overflow: 'hidden' }}>
              {I.vote('white', 14)} Vote for This
            </button>
        </div>
      </div>
    </div>
  );
});

// =============================================================================
// MapLibre GL JS — Snap Map-style vector basemap (smooth GPU-rendered)
// Prefers MapTiler Streets v2 Dark when REACT_APP_MAPTILER_KEY is set
// (denser POIs, road hierarchies, neighborhood labels). Falls back to
// CARTO Dark Matter (free, no key) when the env var is missing.
// =============================================================================
const MAPTILER_KEY = process.env.REACT_APP_MAPTILER_KEY;
// basic-v2 instead of streets-v2 (2026-08-12): streets renders every POI,
// transit stop, and neighborhood label Google-style, which buried Flock's own
// venue markers in basemap noise. Basic keeps roads/water/districts legible
// and lets OUR pins be the loudest thing on the map.
const DARK_VECTOR_STYLE = MAPTILER_KEY
  ? `https://api.maptiler.com/maps/basic-v2-dark/style.json?key=${MAPTILER_KEY}`
  : 'https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json';
// Light-mode basemap (2026-07 redesign): the always-dark map read as a "weird
// overlay" inside the cream app. Basic light in light mode; positron fallback.
const LIGHT_VECTOR_STYLE = MAPTILER_KEY
  ? `https://api.maptiler.com/maps/basic-v2/style.json?key=${MAPTILER_KEY}`
  : 'https://basemaps.cartocdn.com/gl/positron-gl-style/style.json';
const isAppDark = () => document.documentElement.getAttribute('data-theme') === 'dark';
// Pass `dark` explicitly when you have it from React state; omit it to read the
// live <html data-theme> (used at map construction, before any effect runs).
const ROADMAP_STYLE = (dark) => ((dark === undefined ? isAppDark() : dark) ? DARK_VECTOR_STYLE : LIGHT_VECTOR_STYLE);
// Satellite: prefer MapTiler "hybrid" (imagery + roads + place labels overlaid)
// when key is set; falls back to bare ESRI raster imagery if not.
const SATELLITE_STYLE = MAPTILER_KEY
  ? `https://api.maptiler.com/maps/hybrid/style.json?key=${MAPTILER_KEY}`
  : {
      version: 8,
      sources: {
        'esri-imagery': {
          type: 'raster',
          tiles: ['https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'],
          tileSize: 256,
          attribution: 'Tiles © Esri',
          maxzoom: 19,
        },
      },
      layers: [{ id: 'esri-imagery', type: 'raster', source: 'esri-imagery' }],
    };

// AI crowd heatmap paint — matches the old Google HeatmapLayer gradient/radius/opacity.
// MapLibre heatmap-intensity: 2 ≈ Google maxIntensity: 0.5 (1/0.5 = 2× per-point contribution).
const VENUE_HEAT_PAINT = {
  'heatmap-weight': ['coalesce', ['get', 'weight'], 0.5],
  'heatmap-intensity': 4,
  'heatmap-radius': 60,
  'heatmap-opacity': 0.85,
  'heatmap-color': [
    'interpolate', ['linear'], ['heatmap-density'],
    0,    'rgba(0, 0, 0, 0)',
    0.1,  'rgba(34, 197, 94, 0.6)',
    0.2,  'rgba(34, 197, 94, 0.7)',
    0.3,  'rgba(160, 220, 40, 0.75)',
    0.4,  'rgba(250, 204, 21, 0.8)',
    0.5,  'rgba(251, 191, 36, 0.82)',
    0.6,  'rgba(245, 158, 11, 0.85)',
    0.7,  'rgba(249, 115, 22, 0.88)',
    0.8,  'rgba(239, 68, 68, 0.9)',
    0.9,  'rgba(220, 38, 38, 0.94)',
    1,    'rgba(185, 28, 28, 0.97)',
  ],
};

// Add accuracy ring + venue heatmap + 3D buildings.
// Inserts heat UNDER the first symbol layer so road/place labels stay readable
// on top of the heat. 3D building extrusion uses the basemap's existing
// building vector tiles (free, no extra fetch) — gives the map Snap-Map-style
// city depth when zoomed in.
function addOverlayLayers(map) {
  const layers = map.getStyle().layers || [];
  const firstSymbolId = layers.find(l => l.type === 'symbol')?.id;

  if (!map.getSource('user-accuracy')) {
    map.addSource('user-accuracy', { type: 'geojson', data: { type: 'FeatureCollection', features: [] } });
    map.addLayer({ id: 'user-accuracy-fill', type: 'fill', source: 'user-accuracy', paint: { 'fill-color': '#3b82f6', 'fill-opacity': 0.1 } }, firstSymbolId);
    map.addLayer({ id: 'user-accuracy-line', type: 'line', source: 'user-accuracy', paint: { 'line-color': '#3b82f6', 'line-opacity': 0.3, 'line-width': 1 } }, firstSymbolId);
  }
  if (!map.getSource('venue-heat')) {
    map.addSource('venue-heat', { type: 'geojson', data: { type: 'FeatureCollection', features: [] } });
    map.addLayer({ id: 'venue-heat', type: 'heatmap', source: 'venue-heat', paint: VENUE_HEAT_PAINT }, firstSymbolId);
  }

  // 3D building extrusion. Reuses whichever building source-layer the basemap
  // exposes (CARTO/OMT call it 'building'). Skipped when basemap doesn't ship
  // building geometry (e.g. raster satellite style).
  if (!map.getLayer('flock-3d-buildings')) {
    const buildingLayer = layers.find(l => l['source-layer'] === 'building' && (l.type === 'fill' || l.type === 'fill-extrusion'));
    if (buildingLayer) {
      try {
        map.addLayer({
          id: 'flock-3d-buildings',
          source: buildingLayer.source,
          'source-layer': 'building',
          type: 'fill-extrusion',
          minzoom: 14,
          paint: {
            'fill-extrusion-color': '#243651',
            'fill-extrusion-height': [
              'interpolate', ['linear'], ['zoom'],
              14, 0,
              16, ['coalesce', ['get', 'render_height'], ['get', 'height'], 8],
            ],
            'fill-extrusion-base': ['coalesce', ['get', 'render_min_height'], ['get', 'min_height'], 0],
            'fill-extrusion-opacity': 0.75,
          },
        }, firstSymbolId);
      } catch {}
    }
  }
}

// True-meters circle as a GeoJSON polygon for the user's accuracy ring
function metersCirclePolygon(lat, lng, radiusMeters, points = 64) {
  const coords = [];
  const earthR = 6378137;
  const latRad = (lat * Math.PI) / 180;
  for (let i = 0; i <= points; i++) {
    const angle = (i / points) * Math.PI * 2;
    const dLat = (radiusMeters * Math.cos(angle)) / earthR;
    const dLng = (radiusMeters * Math.sin(angle)) / (earthR * Math.cos(latRad));
    coords.push([lng + (dLng * 180) / Math.PI, lat + (dLat * 180) / Math.PI]);
  }
  return { type: 'Feature', geometry: { type: 'Polygon', coordinates: [coords] }, properties: {} };
}

const MapLibreMapView = React.memo(({ venues, filterCategory, userLocation, activeVenue, setActiveVenue, getCategoryColor, pickingVenueForCreate, setPickingVenueForCreate, setSelectedVenueForCreate, setCurrentScreen, openVenueDetail, flockMemberLocations, calcDistance }) => {
  const mapRef = useRef(null);
  const mapRootRef = useRef(null);   // outermost node — see the attribution note in init
  const mapInstanceRef = useRef(null);
  const markersRef = useRef([]); // [{ marker, el, venue }]
  const userMarkerRef = useRef(null);
  const userElRef = useRef(null);
  const memberMarkersRef = useRef({}); // userId -> { marker, popup }
  const photoCacheRef = useRef({}); // place_id -> dataURL
  const prevActiveRef = useRef(null);
  const watchIdRef = useRef(null);
  const mapLibreRef = useRef(null); // holds the maplibre-gl module after dynamic import
  const venuesRef = useRef([]);     // latest venues for non-React consumers (toggleMapType, etc.)
  const fittedKeyRef = useRef(null); // result set the viewport was last framed to
  const [mapReady, setMapReady] = useState(false);
  const [mapType, setMapType] = useState(() => localStorage.getItem('flock_map_type') || 'roadmap');
  /* The basemap follows the app theme. It used to be chosen ONCE, at map
     construction, so flipping to dark mode left three quarters of Discover as a
     bright blue-and-cream rectangle under navy chrome. The style is now swapped
     whenever the theme changes, and every marker colour below is read from the
     matching palette instead of the module-level light-mode constant. */
  const { isDark: mapIsDark } = useTheme();
  const mapPalette = mapIsDark ? colorsDark : colorsLight;
  const appliedDarkRef = useRef(null);

  const DEFAULT_ZOOM = 12;

  // ---------- helpers ----------
  const getUserLocation = () => new Promise((resolve) => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (p) => resolve({ lat: p.coords.latitude, lng: p.coords.longitude }),
        () => resolve({ lat: 40.5798, lng: -75.2932 }),
        { enableHighAccuracy: true, timeout: 8000, maximumAge: 0 },
      );
    } else {
      resolve({ lat: 40.5798, lng: -75.2932 });
    }
  });

  // SVG fallback pin (no photo). Inverted on the dark basemap: a navy pin body
  // on dark tiles was a hole in the map.
  const buildPinSvg = useCallback((isActive, category) => {
    const body = mapIsDark
      ? (isActive ? '#6d9ac3' : '#f1ede0')
      : (isActive ? '#2d5a87' : '#1e293b');
    const edge = mapIsDark ? '#0b1220' : '#f1ede0';
    const disc = mapIsDark ? '#0f172a' : '#ffffff';
    const initialMap = { Food: 'F', Nightlife: 'N', 'Live Music': 'M', Sports: 'S' };
    const initial = initialMap[category] || 'P';
    return `<svg aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 42">` +
      `<defs><filter id="s" x="-20%" y="-10%" width="140%" height="140%"><feDropShadow dx="0" dy="2" stdDeviation="2" flood-opacity="0.35"/></filter></defs>` +
      `<path d="M16 0C7.16 0 0 7.16 0 16c0 12 16 26 16 26s16-14 16-26C32 7.16 24.84 0 16 0z" fill="${body}" stroke="${edge}" stroke-width="2" filter="url(#s)"/>` +
      `<circle cx="16" cy="14.5" r="9" fill="${disc}"/>` +
      `<text x="16" y="18.5" text-anchor="middle" font-size="13" font-weight="bold" font-family="Hanken Grotesk,sans-serif" fill="${body}">${initial}</text>` +
      `</svg>`;
  }, [mapIsDark]);

  // Circular photo pin via canvas (same trick as the old impl, returns dataURL)
  const buildPhotoPin = useCallback((photoUrl, isActive) => {
    const size = isActive ? 54 : 44;
    const border = isActive ? 3.5 : 2.5;
    const borderColor = isActive ? (mapIsDark ? '#6d9ac3' : '#2d5a87') : '#f1ede0';
    return new Promise((resolve) => {
      const canvas = document.createElement('canvas');
      const dpr = 2;
      canvas.width = size * dpr;
      canvas.height = size * dpr;
      const ctx = canvas.getContext('2d');
      ctx.scale(dpr, dpr);
      const r = size / 2;
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        ctx.beginPath();
        ctx.arc(r, r, r - 0.5, 0, Math.PI * 2);
        ctx.fillStyle = borderColor;
        ctx.fill();
        ctx.beginPath();
        ctx.arc(r, r, r - border, 0, Math.PI * 2);
        ctx.clip();
        const aspect = img.width / img.height;
        let sx = 0, sy = 0, sw = img.width, sh = img.height;
        if (aspect > 1) { sx = (img.width - img.height) / 2; sw = img.height; }
        else { sy = (img.height - img.width) / 2; sh = img.width; }
        ctx.drawImage(img, sx, sy, sw, sh, border, border, size - border * 2, size - border * 2);
        resolve(canvas.toDataURL('image/png'));
      };
      img.onerror = () => resolve(null);
      img.src = photoUrl;
    });
  }, [mapIsDark]);

  // Category ring colour. This used to read the module-level `colors`, which is
  // the LIGHT palette regardless of theme — so on the dark basemap the rings
  // were navy on near-black and the pins lost their edge entirely.
  const categoryRingColor = useCallback((cat) => {
    switch (cat) {
      case 'Food': return mapPalette.food;
      case 'Nightlife': return mapPalette.nightlife;
      case 'Live Music': return mapPalette.music;
      case 'Sports': return mapPalette.sports;
      default: return mapPalette.steel;
    }
  }, [mapPalette]);

  // Build a marker DOM element (pin or photo). The OUTER el is owned by MapLibre
  // (it sets transform every frame), so all visual styling + transitions live on
  // an INNER div. Touching transform on the outer el causes pin lag / wrong position.
  const buildMarkerEl = useCallback((venue, isActive) => {
    const el = document.createElement('div');
    el.className = 'mlb-venue-marker';
    el.style.cursor = 'pointer';
    el.style.display = 'flex';
    el.style.flexDirection = 'column';
    el.style.alignItems = 'center';
    // No transition / transform on the outer el — MapLibre owns it.

    const inner = document.createElement('div');
    inner.className = 'mlb-marker-inner';
    inner.style.transition = 'width 0.2s ease, height 0.2s ease, box-shadow 0.2s ease';
    inner.style.willChange = 'auto';
    const size = isActive ? 54 : 44;
    inner.style.width = size + 'px';
    inner.style.height = size + 'px';
    inner.style.display = 'block';

    const ring = categoryRingColor(venue.category);
    const applyPhotoStyle = () => {
      inner.style.backgroundSize = 'cover';
      inner.style.backgroundPosition = 'center';
      inner.style.borderRadius = '50%';
      inner.style.boxShadow = `0 0 0 3px ${ring}, 0 4px 14px rgba(0,0,0,0.35)`;
    };

    const cached = photoCacheRef.current[venue.place_id];
    if (cached) {
      inner.style.backgroundImage = `url("${cached}")`;
      applyPhotoStyle();
    } else if (venue.photo_url) {
      const svg = buildPinSvg(isActive, venue.category);
      inner.innerHTML = svg;
      const svgEl = inner.querySelector('svg');
      if (svgEl) { svgEl.setAttribute('width', size); svgEl.setAttribute('height', Math.round(size * 1.32)); }
      buildPhotoPin(venue.photo_url, isActive).then(dataUrl => {
        if (dataUrl) {
          photoCacheRef.current[venue.place_id] = dataUrl;
          inner.innerHTML = '';
          inner.style.backgroundImage = `url("${dataUrl}")`;
          applyPhotoStyle();
        }
      });
    } else {
      const svg = buildPinSvg(isActive, venue.category);
      inner.innerHTML = svg;
      const svgEl = inner.querySelector('svg');
      if (svgEl) { svgEl.setAttribute('width', size); svgEl.setAttribute('height', Math.round(size * 1.32)); }
    }
    el.appendChild(inner);

    // Name + rating label (Apple-Maps-style). Hidden by default; CSS shows it
    // when the map container reaches data-zoom-tier="hi".
    const label = document.createElement('div');
    label.className = 'mlb-marker-label';
    const ratingHtml = venue.rating || venue.stars
      ? `<span class="mlb-label-rating">★ ${(venue.rating || venue.stars).toFixed ? (venue.rating || venue.stars).toFixed(1) : (venue.rating || venue.stars)}</span>`
      : '';
    label.innerHTML = `<span class="mlb-label-name">${(venue.name || '').replace(/[<>]/g, '')}</span>${ratingHtml}`;
    el.appendChild(label);

    return el;
  }, [buildPinSvg, buildPhotoPin, categoryRingColor]);

  // ---------- init map (once) ----------
  useEffect(() => {
    if (!mapRef.current || mapInstanceRef.current) return;
    let cancelled = false;
    let resizeObs = null;
    const init = async () => {
      const maplibregl = (await import('maplibre-gl')).default;
      mapLibreRef.current = maplibregl;
      if (cancelled) return;
      const userLoc = await getUserLocation();
      if (cancelled) return;
      const savedMapType = localStorage.getItem('flock_map_type') || 'roadmap';

      // A remote basemap style (bad/missing MapTiler key, network, 403) must
      // NOT take the whole app down. A synchronous failure constructing the map
      // is caught here; the async style/tile fetch failures are swallowed by the
      // 'error' listener below. Either way Discover degrades to an empty map
      // instead of throwing up to the root error boundary.
      let map;
      try {
        map = new maplibregl.Map({
          container: mapRef.current,
          style: savedMapType === 'roadmap' ? ROADMAP_STYLE() : SATELLITE_STYLE,
          center: [userLoc.lng, userLoc.lat],
          zoom: DEFAULT_ZOOM,
          minZoom: 3,
          maxZoom: 18,
          // Attribution added manually below at bottom-left (compact) so it
          // never collides with the View-All pill anchored bottom-right.
          attributionControl: false,
          // Snap-style smoothness
          fadeDuration: 200,
          antialias: true,
        });
      } catch (err) {
        console.warn('[Map] Failed to initialize basemap:', err?.message || err);
        return;
      }
      // Without a listener, MapLibre surfaces style/tile load errors (bad key,
      // network) rather than failing quietly. Swallow them so a broken basemap
      // leaves Discover usable.
      map.on('error', (e) => { console.warn('[Map]', e?.error?.message || e?.error || e); });
      map.addControl(new maplibregl.AttributionControl({ compact: true }), 'bottom-left');

      // KEYBOARD ORDER. MapLibre injects its control containers as the FIRST
      // children of the map element, and the map element is the first child of
      // this screen — so the attribution disclosure and its two credit links
      // were the first three tab stops a keyboard user hit, ahead of every
      // Flock control, every time the map was on screen. The credit still has
      // to be reachable (OSM's licence requires it), so it is moved rather than
      // removed: the container becomes the LAST child of the component root, so
      // it is the last tab stop instead of the first. It is absolutely
      // positioned bottom-left against a full-bleed parent either way, so it
      // does not move on screen. The compact disclosure toggle itself is
      // purely visual, so it drops out of the tab sequence (still clickable).
      try {
        const attrib = mapRef.current && mapRef.current.querySelector('.maplibregl-ctrl-bottom-left');
        if (attrib && mapRootRef.current) {
          mapRootRef.current.appendChild(attrib);
          const toggle = attrib.querySelector('.maplibregl-ctrl-attrib-button');
          if (toggle) toggle.setAttribute('tabindex', '-1');
        }
      } catch { /* attribution stays where MapLibre put it */ }
      mapInstanceRef.current = map;

      // Snappier scroll-wheel zoom — default 1/300 feels sluggish vs Snap Map.
      if (map.scrollZoom) {
        map.scrollZoom.setZoomRate(1 / 100);   // 3× faster per pixel
        map.scrollZoom.setWheelZoomRate(1 / 80); // 5× faster per wheel notch
      }

      // Track container size — MapLibre locks canvas dimensions at construction,
      // so if the parent flex layout settles AFTER init the canvas stays short
      // (leaves a navy gap below the map). ResizeObserver fixes that for good
      // and also handles orientation changes / window resize.
      if (typeof ResizeObserver !== 'undefined') {
        resizeObs = new ResizeObserver(() => { try { map.resize(); } catch {} });
        resizeObs.observe(mapRef.current);
      } else {
        // Fallback: nudge once after layout settles
        setTimeout(() => { try { map.resize(); } catch {} }, 0);
      }

      // Tier the map's container by zoom so CSS can scale + label markers
      // without re-rendering the React tree on every wheel notch.
      const applyZoomTier = () => {
        const z = map.getZoom();
        const container = mapRef.current;
        if (!container) return;
        // hi  → labels visible, full-size markers
        // mid → no labels, full-size
        // lo  → no labels, shrunk markers (zoomed-out density)
        const tier = z >= 15 ? 'hi' : z >= 13 ? 'mid' : 'lo';
        if (container.dataset.zoomTier !== tier) container.dataset.zoomTier = tier;
      };

      // Brighten native basemap POI labels (MapTiler's Streets v2 Dark dims them
      // hard, which is why the map feels emptier than Apple's). We bump opacity
      // and lower the minzoom so cafés/restaurants show earlier.
      const boostNativePoiLabels = () => {
        if (!isAppDark()) return; // pale-label boost is tuned for the dark basemap only
        const style = map.getStyle && map.getStyle();
        if (!style?.layers) return;
        for (const layer of style.layers) {
          if (layer.type !== 'symbol') continue;
          const id = layer.id || '';
          const sl = layer['source-layer'] || '';
          const looksPoi = /poi|place_label/i.test(id) || /poi|place/i.test(sl);
          if (!looksPoi) continue;
          try {
            map.setLayoutProperty(layer.id, 'visibility', 'visible');
            // Lower the zoom at which labels appear (default ~14 → 12.5)
            if (typeof layer.minzoom === 'number' && layer.minzoom > 12.5) {
              map.setLayerZoomRange(layer.id, 12.5, layer.maxzoom ?? 24);
            }
            map.setPaintProperty(layer.id, 'text-opacity', 0.95);
            map.setPaintProperty(layer.id, 'text-color', '#e2e8f0');
            map.setPaintProperty(layer.id, 'text-halo-color', 'rgba(15,23,42,0.85)');
            map.setPaintProperty(layer.id, 'text-halo-width', 1.4);
          } catch { /* layer may not support a property — ignore */ }
        }
      };

      map.on('load', () => {
        addOverlayLayers(map);
        applyZoomTier();
        boostNativePoiLabels();
        setMapReady(true);
      });

      // Re-apply both on style swap (roadmap ↔ satellite)
      map.on('styledata', () => {
        applyZoomTier();
        boostNativePoiLabels();
      });

      map.on('zoom', applyZoomTier);

      // Click on empty map — clear active venue
      map.on('click', (e) => {
        if (e.originalEvent?.target?.closest?.('.mlb-venue-marker')) return;
        setActiveVenue(null);
      });

      // Re-pan when geolocation permission flips to granted
      if (navigator.permissions) {
        navigator.permissions.query({ name: 'geolocation' }).then((perm) => {
          perm.addEventListener('change', () => {
            if (perm.state === 'granted') {
              navigator.geolocation.getCurrentPosition(
                (pos) => map.flyTo({ center: [pos.coords.longitude, pos.coords.latitude], zoom: DEFAULT_ZOOM }),
                () => {},
                { enableHighAccuracy: true, timeout: 8000, maximumAge: 0 },
              );
            }
          });
        }).catch(() => {});
      }
    };
    init();
    return () => { cancelled = true; if (resizeObs) resizeObs.disconnect(); };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  /* setStyle throws away every source and layer the app added, so anything
     Flock owns has to go back on afterwards. Shared by the satellite toggle and
     the light/dark swap below. (HTML markers survive a style swap; sources and
     layers do not.) */
  const rehydrateAfterStyleSwap = useCallback((map) => {
    addOverlayLayers(map);
    // Re-feed accuracy data
    if (userLocation) {
      const src = map.getSource('user-accuracy');
      if (src) src.setData({ type: 'FeatureCollection', features: [metersCirclePolygon(userLocation.lat, userLocation.lng, userLocation.accuracy || 50)] });
    }
    // Re-feed heatmap data from current venues
    const heatSrc = map.getSource('venue-heat');
    if (heatSrc) {
      const features = (venuesRef.current || [])
        .filter(v => typeof v.crowd === 'number' && v.location?.latitude && v.location?.longitude)
        .map(v => ({ type: 'Feature', geometry: { type: 'Point', coordinates: [v.location.longitude, v.location.latitude] }, properties: { weight: v.crowd / 100 } }));
      heatSrc.setData({ type: 'FeatureCollection', features });
    }
  }, [userLocation]);

  // ---------- map type toggle (vector dark <-> satellite) ----------
  const toggleMapType = useCallback(async () => {
    const map = mapInstanceRef.current;
    if (!map) return;
    const newType = mapType === 'roadmap' ? 'hybrid' : 'roadmap';
    setMapType(newType);
    localStorage.setItem('flock_map_type', newType);
    queueSync({ mapType: newType });
    map.setStyle(newType === 'roadmap' ? ROADMAP_STYLE(mapIsDark) : SATELLITE_STYLE);
    map.once('styledata', () => rehydrateAfterStyleSwap(map));
  }, [mapType, mapIsDark, rehydrateAfterStyleSwap]);

  // ---------- basemap follows the app theme ----------
  useEffect(() => {
    const map = mapInstanceRef.current;
    if (!mapReady || !map) return;
    // First pass records the theme the map was constructed with; only a real
    // change after that costs a style fetch.
    if (appliedDarkRef.current === null) { appliedDarkRef.current = mapIsDark; return; }
    if (appliedDarkRef.current === mapIsDark) return;
    appliedDarkRef.current = mapIsDark;
    if (mapType !== 'roadmap') return; // satellite imagery has no light/dark twin
    map.setStyle(ROADMAP_STYLE(mapIsDark));
    map.once('styledata', () => rehydrateAfterStyleSwap(map));
  }, [mapIsDark, mapReady, mapType, rehydrateAfterStyleSwap]);

  // ---------- user blue dot + accuracy ring ----------
  useEffect(() => {
    const map = mapInstanceRef.current;
    if (!mapReady || !map || !userLocation) return;
    const lng = userLocation.lng, lat = userLocation.lat;
    const acc = userLocation.accuracy || 50;

    // Blue dot — outer el is owned by MapLibre; pulse animations target the inner div.
    if (!userMarkerRef.current) {
      const el = document.createElement('div');
      el.style.width = '20px';
      el.style.height = '20px';
      const inner = document.createElement('div');
      inner.className = 'mlb-user-dot-inner';
      inner.style.width = '20px';
      inner.style.height = '20px';
      inner.style.borderRadius = '50%';
      inner.style.background = '#3b82f6';
      inner.style.border = '3px solid #fff';
      inner.style.boxShadow = '0 0 0 3px rgba(59,130,246,0.25)';
      inner.style.transition = 'box-shadow 0.4s ease';
      el.appendChild(inner);
      userElRef.current = inner; // pulse helper writes to the inner div
      const ml = mapLibreRef.current;
      if (!ml) return;
      userMarkerRef.current = new ml.Marker({ element: el, anchor: 'center' }).setLngLat([lng, lat]).addTo(map);
    } else {
      userMarkerRef.current.setLngLat([lng, lat]);
    }

    // Accuracy circle data
    const src = map.getSource('user-accuracy');
    if (src) {
      src.setData({ type: 'FeatureCollection', features: [metersCirclePolygon(lat, lng, acc)] });
    }
  }, [userLocation, mapReady]);

  // Live position tracking
  useEffect(() => {
    if (!mapReady || !navigator.geolocation) return;
    if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current);
    watchIdRef.current = navigator.geolocation.watchPosition(
      (pos) => {
        const map = mapInstanceRef.current;
        if (!map) return;
        const lat = pos.coords.latitude, lng = pos.coords.longitude;
        if (userMarkerRef.current) userMarkerRef.current.setLngLat([lng, lat]);
        const src = map.getSource('user-accuracy');
        if (src) src.setData({ type: 'FeatureCollection', features: [metersCirclePolygon(lat, lng, pos.coords.accuracy || 50)] });
      },
      () => {},
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 10000 },
    );
    return () => { if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current); };
  }, [mapReady]);

  // ---------- venue markers ----------
  useEffect(() => {
    const map = mapInstanceRef.current;
    if (!mapReady || !map) return;

    const ml = mapLibreRef.current;
    if (!ml) return;
    venuesRef.current = venues;

    // Clear previous markers
    markersRef.current.forEach(({ marker }) => marker.remove());
    markersRef.current = [];

    const heatFeatures = [];
    venues.forEach(v => {
      const loc = v.location;
      if (!loc?.latitude || !loc?.longitude) return;

      // Heatmap point — weighted by crowd score (0-100 → 0-1)
      if (typeof v.crowd === 'number') {
        heatFeatures.push({
          type: 'Feature',
          geometry: { type: 'Point', coordinates: [loc.longitude, loc.latitude] },
          properties: { weight: v.crowd / 100 },
        });
      }

      const isActive = activeVenue?.id === v.id;
      const el = buildMarkerEl(v, isActive);
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        setActiveVenue(v);
        map.flyTo({ center: [loc.longitude, loc.latitude], zoom: Math.max(map.getZoom(), 15), duration: 600 });
      });
      const anchor = (photoCacheRef.current[v.place_id] || v.photo_url) ? 'center' : 'bottom';
      const marker = new ml.Marker({ element: el, anchor }).setLngLat([loc.longitude, loc.latitude]).addTo(map);
      markersRef.current.push({ marker, el, venue: v });
    });

    // Push heat data to the source
    const heatSrc = map.getSource('venue-heat');
    if (heatSrc) heatSrc.setData({ type: 'FeatureCollection', features: heatFeatures });

    /* FRAME THE RESULTS. The map opened centred on the user at a fixed zoom,
       so a search could return 20 venues and show none of them: the chip said
       "All 20 results" over what looked like an empty map. Fit the viewport to
       the pins whenever the RESULT SET changes (not on every render, or a
       pan would snap back under the user's finger). maxZoom keeps a single
       result from diving to street level. */
    const key = venues.map(v => v.place_id || v.id).join(',');
    if (key === fittedKeyRef.current) return;
    fittedKeyRef.current = key;

    const points = venues
      .filter(v => v.location?.latitude && v.location?.longitude)
      .map(v => [v.location.longitude, v.location.latitude]);
    if (points.length === 0) return;

    /* Places sometimes returns one result on the other side of the country
       (a search around Bethlehem PA came back with a shop in California).
       Fitting to the raw extent then zooms out to the whole continent, which
       is a worse empty map than the one this is fixing. So fit to the CLUSTER:
       take the median point and drop anything absurdly far from it. The
       outlier keeps its pin and its place in the list; it just does not get
       to decide the viewport. */
    const sortedLng = points.map(p => p[0]).slice().sort((a, b) => a - b);
    const sortedLat = points.map(p => p[1]).slice().sort((a, b) => a - b);
    const midLng = sortedLng[sortedLng.length >> 1];
    const midLat = sortedLat[sortedLat.length >> 1];
    const kmFromMid = ([lng, lat]) => Math.hypot(
      (lng - midLng) * 111 * Math.cos(midLat * Math.PI / 180),
      (lat - midLat) * 111,
    );
    const sortedDist = points.map(kmFromMid).sort((a, b) => a - b);
    const medianDist = sortedDist[sortedDist.length >> 1] || 0;
    const limitKm = Math.max(15, medianDist * 4);
    let core = points.filter(p => kmFromMid(p) <= limitKm);
    if (core.length < 2) core = points;

    const bounds = core.reduce(
      (b, p) => b.extend(p),
      new ml.LngLatBounds(core[0], core[0]),
    );
    try {
      map.fitBounds(bounds, {
        padding: { top: 90, bottom: 190, left: 40, right: 40 }, // search bar above, venue cards below
        maxZoom: 15,
        duration: 600,
      });
    } catch { /* container not measured yet — the next result set re-fits */ }
  }, [venues, mapReady, buildMarkerEl]); // eslint-disable-line react-hooks/exhaustive-deps

  // ---------- active venue highlight (only resize the 2 changed markers) ----------
  useEffect(() => {
    const prevId = prevActiveRef.current;
    const newId = activeVenue?.id;
    if (prevId === newId) return;
    prevActiveRef.current = newId;
    markersRef.current.forEach(({ el, venue }) => {
      if (venue.id !== prevId && venue.id !== newId) return;
      const isActive = venue.id === newId;
      const size = isActive ? 54 : 44;
      const inner = el.querySelector('.mlb-marker-inner') || el;
      inner.style.width = size + 'px';
      inner.style.height = size + 'px';
      // Tiny z-index range — the venue card overlay must always sit above markers.
      // (Active = 3, top rated = 2, normal = 1.)
      el.style.zIndex = isActive ? '3' : (venue.topRated ? '2' : '1');
      const svgEl = inner.querySelector('svg');
      if (svgEl) {
        svgEl.setAttribute('width', size);
        svgEl.setAttribute('height', Math.round(size * 1.32));
      } else if (photoCacheRef.current[venue.place_id] && isActive && venue.photo_url) {
        buildPhotoPin(venue.photo_url, true).then(dataUrl => {
          if (dataUrl) {
            photoCacheRef.current[venue.place_id] = dataUrl;
            inner.style.backgroundImage = `url("${dataUrl}")`;
          }
        });
      }
    });
  }, [activeVenue, buildPhotoPin]);

  // ---------- category filter (toggle visibility) ----------
  useEffect(() => {
    markersRef.current.forEach(({ el, venue: v }) => {
      const t = (v.types || []).join(' ').toLowerCase();
      const nm = (v.name || '').toLowerCase();
      let show = true;
      if (filterCategory && filterCategory !== 'All') {
        if (filterCategory === 'Food') {
          show = t.includes('restaurant') || t.includes('cafe') || t.includes('food') || t.includes('bakery') || t.includes('meal') || t.includes('pizza') || t.includes('diner') || t.includes('bar') || t.includes('juice') || t.includes('smoothie') || t.includes('brunch') || t.includes('breakfast') || v.category === 'Food';
        } else if (filterCategory === 'Nightlife') {
          show = t.includes('bar') || t.includes('night_club') || t.includes('club') || t.includes('liquor') || t.includes('lounge') || v.category === 'Nightlife';
        } else if (filterCategory === 'Live Music') {
          show = t.includes('music') || t.includes('concert') || t.includes('performing_arts') || nm.includes('music') || nm.includes('jazz') || v.category === 'Live Music';
        } else if (filterCategory === 'Sports') {
          show = t.includes('stadium') || t.includes('gym') || t.includes('sports') || t.includes('bowling') || t.includes('fitness') || nm.includes('sport') || v.category === 'Sports';
        }
      }
      el.style.display = show ? '' : 'none';
    });
  }, [filterCategory]);

  // ---------- external imperative API ----------
  useEffect(() => {
    const map = mapInstanceRef.current;

    window.__flockOpenVenue = (placeId) => {
      const v = venues.find(venue => venue.place_id === placeId);
      if (v) openVenueDetail(placeId, { name: v.name, formatted_address: v.addr, place_id: placeId, rating: v.stars, photo_url: v.photo_url });
    };

    window.__flockPanToVenue = (target) => {
      if (!map) return;
      const placeId = typeof target === 'string' ? target : target?.place_id;
      const fLat = typeof target === 'object' ? parseFloat(target?.lat) : NaN;
      const fLng = typeof target === 'object' ? parseFloat(target?.lng) : NaN;

      const entry = placeId ? markersRef.current.find(e => e.venue.place_id === placeId) : null;
      if (entry) {
        const loc = entry.venue.location;
        map.flyTo({ center: [loc.longitude, loc.latitude], zoom: 17, duration: 700 });
        setActiveVenue(entry.venue);
        // Bounce — animate the INNER div's top offset (outer transform is MapLibre's)
        const inner = entry.el.querySelector('.mlb-marker-inner');
        if (inner) {
          inner.style.transition = 'top 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
          inner.style.position = 'relative';
          inner.style.top = '-12px';
          setTimeout(() => { inner.style.top = '0px'; }, 250);
          setTimeout(() => { inner.style.transition = 'width 0.2s ease, height 0.2s ease, box-shadow 0.2s ease'; inner.style.position = ''; inner.style.top = ''; }, 700);
        }
      } else if (!isNaN(fLat) && !isNaN(fLng)) {
        map.flyTo({ center: [fLng, fLat], zoom: 17, duration: 700 });
        const nearby = markersRef.current.find(e => {
          const loc = e.venue.location;
          if (!loc) return false;
          const d = Math.sqrt(Math.pow(loc.latitude - fLat, 2) + Math.pow(loc.longitude - fLng, 2)) * 111000;
          return d < 100;
        });
        if (nearby) {
          setActiveVenue(nearby.venue);
        } else {
          // Drop a temp pin
          const venueName = target?.name || 'Venue';
          const venueAddr = target?.address || '';
          // A rating only exists if Google gave us one. It used to default to
          // 4.0, which renders next to a star as if it were measured.
          const venueRating = target?.rating ? parseFloat(target.rating) : null;
          const venuePhoto = target?.photo_url || null;
          // Crowd, price and "best time" were all derived from the first
          // character of the venue name plus its latitude. That is the third
          // instance of the invented-number pattern in this file; the other two
          // carry comments saying so. Nothing here is measured, so nothing here
          // gets a number. The real score arrives with the crowd fetch.
          const tempVenue = {
            id: 'temp_nav_' + Date.now(),
            place_id: placeId || null,
            name: venueName,
            addr: venueAddr,
            type: target?.types?.[0] ? target.types[0].replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase()) : 'Place',
            category: (() => { const tt = (target?.types || []).join(' ').toLowerCase(); if (tt.includes('bar') || tt.includes('night_club')) return 'Nightlife'; if (tt.includes('restaurant') || tt.includes('cafe') || tt.includes('food') || tt.includes('diner') || tt.includes('juice')) return 'Food'; return 'Food'; })(),
            price: null,
            stars: venueRating,
            crowd: null,
            topRated: false,
            photo_url: venuePhoto,
            location: { latitude: fLat, longitude: fLng },
            types: [],
          };
          const ml = mapLibreRef.current;
          if (ml) {
            const el = buildMarkerEl(tempVenue, true);
            el.addEventListener('click', (e) => { e.stopPropagation(); setActiveVenue(tempVenue); map.flyTo({ center: [fLng, fLat], zoom: 17 }); });
            const anchor = venuePhoto ? 'center' : 'bottom';
            const marker = new ml.Marker({ element: el, anchor }).setLngLat([fLng, fLat]).addTo(map);
            markersRef.current.push({ marker, el, venue: tempVenue });
          }
          setActiveVenue(tempVenue);
          if (placeId) openVenueDetail(placeId, { name: venueName, formatted_address: venueAddr, place_id: placeId, rating: venueRating, photo_url: venuePhoto });
        }
      }
    };

    window.__flockGoToMyLocation = () => {
      if (!map) return;
      if (userMarkerRef.current) {
        const ll = userMarkerRef.current.getLngLat();
        map.flyTo({ center: [ll.lng, ll.lat], zoom: 15, duration: 600 });
        // Pulse the dot — box-shadow on the inner div only (transform is owned by MapLibre on the outer)
        if (userElRef.current) {
          userElRef.current.style.boxShadow = '0 0 0 12px rgba(59,130,246,0.35)';
          setTimeout(() => {
            if (userElRef.current) userElRef.current.style.boxShadow = '0 0 0 3px rgba(59,130,246,0.25)';
          }, 500);
        }
        return;
      }
      const center = map.getCenter();
      if (center) map.flyTo({ center: [center.lng, center.lat], zoom: 15 });
    };

    return () => { delete window.__flockOpenVenue; delete window.__flockPanToVenue; delete window.__flockGoToMyLocation; };
  }, [venues, openVenueDetail, setActiveVenue, buildMarkerEl]);

  // ---------- flock member live location markers ----------
  useEffect(() => {
    const map = mapInstanceRef.current;
    if (!mapReady || !map || !flockMemberLocations) return;
    const ml = mapLibreRef.current;
    if (!ml) return;
    const run = (mlMod) => {
      const currentIds = new Set(Object.keys(flockMemberLocations));
      // Remove gone
      Object.keys(memberMarkersRef.current).forEach(uid => {
        if (!currentIds.has(uid)) {
          memberMarkersRef.current[uid].marker.remove();
          delete memberMarkersRef.current[uid];
        }
      });
      Object.entries(flockMemberLocations).forEach(([uid, loc]) => {
        const lng = loc.lng, lat = loc.lat;
        const initial = (loc.name || '?')[0].toUpperCase();
        const dist = userLocation ? calcDistance(userLocation.lat, userLocation.lng, loc.lat, loc.lng) : '';
        const age = Math.round((Date.now() - loc.timestamp) / 1000);
        const ageStr = age < 10 ? 'just now' : age < 60 ? `${age}s ago` : `${Math.round(age / 60)}m ago`;
        const popupHtml = `<div style="font-family:'Hanken Grotesk',-apple-system,system-ui,sans-serif;display:flex;align-items:center;gap:10px;padding:6px 4px;min-width:160px">
          <div style="width:36px;height:36px;border-radius:18px;background:linear-gradient(135deg,#1e293b,#1a3a5c);display:flex;align-items:center;justify-content:center;flex-shrink:0">
            <span style="color:white;font-size:15px;font-weight:700">${initial}</span>
          </div>
          <div style="flex:1;min-width:0">
            <div style="font-size:13px;font-weight:700;color:#1e293b;margin:0 0 2px">${loc.name}</div>
            <div style="display:flex;align-items:center;gap:4px">
              <span style="width:6px;height:6px;border-radius:3px;background:#22c55e;display:inline-block"></span>
              <span style="font-size: 12px;color:#4b5563;font-weight:500">${dist ? dist + ' away · ' + ageStr : 'Live'}</span>
            </div>
          </div>
        </div>`;

        if (memberMarkersRef.current[uid]) {
          memberMarkersRef.current[uid].marker.setLngLat([lng, lat]);
          if (memberMarkersRef.current[uid].popup) memberMarkersRef.current[uid].popup.setHTML(popupHtml);
        } else {
          const el = document.createElement('div');
          el.style.width = '40px';
          el.style.height = '40px';
          el.style.cursor = 'pointer';
          el.innerHTML = `<svg aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 40 40">
            <circle cx="20" cy="20" r="18" fill="#1e293b" stroke="white" stroke-width="3"/>
            <circle cx="20" cy="20" r="18" fill="none" stroke="#22c55e" stroke-width="2" stroke-dasharray="4 4" opacity="0.6"/>
            <text x="20" y="26" text-anchor="middle" fill="white" font-size="16" font-weight="bold" font-family="Hanken Grotesk,sans-serif">${initial}</text>
          </svg>`;
          const popup = new mlMod.Popup({ offset: 25, closeButton: false }).setHTML(popupHtml);
          const marker = new mlMod.Marker({ element: el, anchor: 'center' }).setLngLat([lng, lat]).setPopup(popup).addTo(map);
          memberMarkersRef.current[uid] = { marker, popup };
        }
      });
    };
    run(ml);
  }, [mapReady, flockMemberLocations, userLocation, calcDistance]);

  // ---------- render ----------
  return (
    <div ref={mapRootRef} style={{ position: 'absolute', inset: 0 }}>
      {!mapReady && (
        <div style={{ position: 'absolute', inset: 0, zIndex: 10, backgroundColor: '#1a2a3a', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: '12px' }}>
          <div style={{ width: '32px', height: '32px', border: '3px solid rgba(255,255,255,0.15)', borderTopColor: '#6d9ac3', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
          <p style={{ color: '#8ec3b9', fontSize: 'var(--t-label)', fontWeight: '500', margin: 0 }}>Loading map...</p>
        </div>
      )}
      <style>{`
        /* opacity 0.4 on top of grey-on-white put the legally-required credit
           well under 4.5:1. Full opacity; MapLibre's own colours are readable. */
        .maplibregl-ctrl-attrib { font-size: 12px !important; opacity: 1; }
        .maplibregl-ctrl-attrib a { color: #33475e; }
        .maplibregl-ctrl-logo { display: none !important; }
        .mlb-venue-marker { user-select: none; -webkit-user-select: none; }
        /* Markers must never bleed above overlay UI (venue cards, sheets, etc.) */
        .maplibregl-marker { z-index: 1; }
        .maplibregl-canvas-container { z-index: 0; }

        /* ---- Apple-Maps-style name label under each pin ---- */
        .mlb-marker-label {
          margin-top: 4px;
          padding: 3px 7px;
          border-radius: 8px;
          background: rgba(15,23,42,0.78);
          backdrop-filter: blur(8px);
          -webkit-backdrop-filter: blur(8px);
          color: #f1f5f9;
          font-family: 'Hanken Grotesk', system-ui, -apple-system, sans-serif;
          font-size: 12px;
          font-weight: 700;
          letter-spacing: -0.1px;
          line-height: 1.15;
          box-shadow: 0 2px 8px rgba(0,0,0,0.35), 0 0 0 1px rgba(255,255,255,0.06);
          opacity: 0;
          transform: translateY(-4px) scale(0.85);
          transition: opacity 0.18s ease, transform 0.18s ease;
          pointer-events: none;
          max-width: 180px;
          display: flex;
          align-items: center;
          gap: 5px;
        }
        .mlb-label-name {
          /* Allow up to 2 lines on long names; ellipsize if it still overflows. */
          display: -webkit-box;
          -webkit-line-clamp: 2;
          -webkit-box-orient: vertical;
          overflow: hidden;
          text-overflow: ellipsis;
          word-break: break-word;
        }
        .mlb-label-rating {
          color: #fbbf24;
          font-weight: 800;
          font-size: 12px;
          letter-spacing: 0;
        }

        /* Show labels only when zoomed in enough to read them. */
        [data-zoom-tier="hi"] .mlb-marker-label {
          opacity: 1;
          transform: translateY(0) scale(1);
        }

        /* Shrink markers when zoomed out so the map doesn't get blanketed. */
        [data-zoom-tier="lo"] .mlb-marker-inner {
          transform: scale(0.65);
          transform-origin: center center;
          transition: transform 0.18s ease, width 0.2s ease, height 0.2s ease, box-shadow 0.2s ease;
        }
        [data-zoom-tier="mid"] .mlb-marker-inner,
        [data-zoom-tier="hi"] .mlb-marker-inner {
          transform: scale(1);
          transition: transform 0.18s ease, width 0.2s ease, height 0.2s ease, box-shadow 0.2s ease;
        }
      `}</style>
      <div ref={mapRef} style={{ width: '100%', height: '100%' }} />

      {/* My Location button */}
      <button aria-label="My Location" className="hit44"
        onClick={() => window.__flockGoToMyLocation && window.__flockGoToMyLocation()}
        style={{
          position: 'absolute', bottom: '80px', right: '12px',
          width: '44px', height: '44px', borderRadius: '22px',
          border: 'none', background: 'var(--bg-card-solid)', cursor: 'pointer',
          boxShadow: '0 2px 8px rgba(0,0,0,0.25)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          zIndex: 5, transition: 'transform 0.2s ease',
        }}
        onMouseEnter={(e) => { e.currentTarget.style.transform = 'scale(1.1)'; }}
        onMouseLeave={(e) => { e.currentTarget.style.transform = 'scale(1)'; }}
        title="My Location"
      >
        <svg aria-hidden="true" focusable="false" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#3b82f6" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
          <circle cx="12" cy="12" r="4"/><line x1="12" y1="2" x2="12" y2="6"/><line x1="12" y1="18" x2="12" y2="22"/><line x1="2" y1="12" x2="6" y2="12"/><line x1="18" y1="12" x2="22" y2="12"/>
        </svg>
      </button>

      {/* Zoom controls */}
      <div style={{
        position: 'absolute', bottom: '184px', right: '12px',
        display: 'flex', flexDirection: 'column',
        borderRadius: '22px', overflow: 'hidden',
        boxShadow: '0 2px 8px rgba(0,0,0,0.25)', zIndex: 5,
      }}>
        <button aria-label="Zoom in" className="hit44"
          onClick={() => mapInstanceRef.current && mapInstanceRef.current.zoomIn({ duration: 150 })}
          style={{ width: '44px', height: '40px', border: 'none', background: 'var(--bg-card-solid)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
          title="Zoom in"
        >
          <svg aria-hidden="true" focusable="false" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="var(--text-primary)" strokeWidth="2.5" strokeLinecap="round">
            <line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/>
          </svg>
        </button>
        <div style={{ height: '1px', background: 'var(--border-default)' }} />
        <button aria-label="Zoom out" className="hit44"
          onClick={() => mapInstanceRef.current && mapInstanceRef.current.zoomOut({ duration: 150 })}
          style={{ width: '44px', height: '40px', border: 'none', background: 'var(--bg-card-solid)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
          title="Zoom out"
        >
          <svg aria-hidden="true" focusable="false" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="var(--text-primary)" strokeWidth="2.5" strokeLinecap="round">
            <line x1="5" y1="12" x2="19" y2="12"/>
          </svg>
        </button>
      </div>

      {/* Map / Satellite toggle */}
      <button className="hit44"
        aria-label={mapType === 'roadmap' ? 'Switch to satellite view' : 'Switch to map view'}
        onClick={toggleMapType}
        style={{
          position: 'absolute', bottom: '132px', right: '12px',
          width: '44px', height: '44px', borderRadius: '22px',
          border: 'none', background: 'var(--bg-card-solid)', cursor: 'pointer',
          boxShadow: '0 2px 8px rgba(0,0,0,0.25)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          zIndex: 5, transition: 'transform 0.2s ease',
        }}
        onMouseEnter={(e) => { e.currentTarget.style.transform = 'scale(1.1)'; }}
        onMouseLeave={(e) => { e.currentTarget.style.transform = 'scale(1)'; }}
        title={mapType === 'roadmap' ? 'Switch to Satellite' : 'Switch to Map'}
      >
        {mapType === 'roadmap' ? (
          <svg aria-hidden="true" focusable="false" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="var(--text-primary)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <circle cx="12" cy="12" r="10"/><path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20"/><path d="M2 12h20"/>
          </svg>
        ) : (
          <svg aria-hidden="true" focusable="false" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="var(--text-primary)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <polygon points="1 6 1 22 8 18 16 22 23 18 23 2 16 6 8 2 1 6"/><line x1="8" y1="2" x2="8" y2="18"/><line x1="16" y1="6" x2="16" y2="22"/>
          </svg>
        )}
      </button>
    </div>
  );
});

